package org.codex.nfsugpreview;
import java.nio.*;import java.nio.file.*;import java.util.*;
public final class RetainedSceneTest {
 static NativeSourceSceneBinding.Source provider(Path dir,String extension,Map<String,byte[]> inputs){return (e,s,b,f)->{try{String name="owner-"+s+extension;byte[] raw=Files.readAllBytes(dir.resolve(name));inputs.put(name,raw);return raw;}catch(Exception failure){throw new RuntimeException(failure);}};}
 static NativeSourceSceneBinding.Source forged(NativeSourceSceneBinding.Source source,int offset){return(e,s,b,f)->{byte[] raw=source.packet(e,s,b,f).clone();ByteBuffer.wrap(raw).order(ByteOrder.LITTLE_ENDIAN).putLong(offset,ByteBuffer.wrap(raw).order(ByteOrder.LITTLE_ENDIAN).getLong(offset)+1);return raw;};}
 static void reject(byte[] raw,NativeSourceSceneBinding.Source r,NativeSourceSceneBinding.Source w,NativeSourceSceneBinding.Source p){try{NativeRetainedScene.capture(raw,r,w,p);throw new AssertionError("Forged component accepted");}catch(IllegalArgumentException expected){}}
 public static void main(String[] args)throws Exception{Path dir=Paths.get(args[0]);int frames=0,missing=0,forged=0,roadCells=0,wallCells=0;if(NativeRetainedScene.capture(null,null,null,null)!=null)throw new AssertionError("Missing background accepted");try(DirectoryStream<Path> files=Files.newDirectoryStream(dir,"source-race-background-*.nrb")){for(Path file:files){byte[] raw=Files.readAllBytes(file);Map<String,byte[]> inputs=new HashMap<>();NativeSourceSceneBinding.Source road=provider(dir,".nrh",inputs),wall=provider(dir,".nwh",inputs),proof=provider(dir,".nrp",inputs);NativeRetainedScene frame=NativeRetainedScene.capture(raw,road,wall,proof);if(frame==null||!frame.roads.belongsTo(frame.background.sky.scene)||!frame.walls.belongsTo(frame.background.sky.scene))throw new AssertionError("Incomplete frame");roadCells+=frame.roads.cells();wallCells+=frame.walls.cells();
 if(NativeRetainedScene.capture(raw,(e,s,b,f)->null,wall,proof)!=null||NativeRetainedScene.capture(raw,road,(e,s,b,f)->null,proof)!=null||NativeRetainedScene.capture(raw,road,wall,(e,s,b,f)->null)!=null)throw new AssertionError("Missing component accepted");missing+=3;reject(raw,forged(road,24),wall,proof);reject(raw,road,forged(wall,24),proof);reject(raw,road,wall,forged(proof,24));reject(raw,road,wall,forged(proof,32));forged+=4;
 byte[] expected=new byte[153600];frame.background.exactRgba().get(expected);NativeRoadRetention.Draw draw=frame.roads.draw(0);byte value=frame.roads.texture(draw).get(draw.records()[2]);Arrays.fill(raw,(byte)0);for(byte[] input:inputs.values())Arrays.fill(input,(byte)0);byte[] actual=new byte[153600];frame.background.exactRgba().get(actual);if(!Arrays.equals(actual,expected)||frame.roads.texture(draw).get(draw.records()[2])!=value)throw new AssertionError("Mutable caller input");frames++;
 }}if(frames!=9||roadCells!=100870||wallCells!=206571||missing!=27||forged!=36)throw new AssertionError("Incomplete verification");System.out.println("PASS_RETAINED_SCENE frames="+frames+" road_cells="+roadCells+" wall_cells="+wallCells+" missing_rejected="+missing+" forged_rejected="+forged+" immutable=true");}
}

